mapper.select:
SELECT ar.id, ar.user_id, fu.avatar, fu.sex, fu.nick_name as nickName, ar.type, ar.city, ar.content, ar.img, ar.like_count, ar.comment_count, ar.create_time, fu.job_mes, fu.birth_date, case when (select count(1) from user_to_like ut where ut.del_flag=0 and ut.praise_type='ARTICLE' and ut.target_id=ar.id and ut.user_id=#{userId})=0 then false else true end as isLike FROM article ar LEFT JOIN t_user fu ON ar.user_id = fu.id
ar.id=#{id}
order by ar.id desc
